using System.Net;using System.Net.Http.Headers;using SyWater.Places.Application.Ports.Out;namespace SyWater.Places.Infrastructure.Devices;public sealed class HttpDeviceLinkChecker(HttpClient http, IAccessTokenProvider tokens) : IDeviceLinkChecker{    public const string ServiceName = "device-service";    public async Task<bool> HasActiveDeviceAsync(Guid placeId, CancellationToken ct)    {        var token = tokens.GetAccessToken()                    ?? throw new InvalidOperationException("There is no access token in the current request.");        using var request = new HttpRequestMessage(HttpMethod.Get, $"api/places/{placeId}/device");        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);        try        {            using var response = await http.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, ct);            return response.StatusCode switch            {                HttpStatusCode.OK => true,                HttpStatusCode.NotFound => false,                _ => throw new ExternalServiceUnavailableException(ServiceName,                    new HttpRequestException($"Unexpected status {(int)response.StatusCode}.")),            };        }        catch (HttpRequestException ex)        {            throw new ExternalServiceUnavailableException(ServiceName, ex);        }        catch (TaskCanceledException ex) when (!ct.IsCancellationRequested)        {            throw new ExternalServiceUnavailableException(ServiceName, ex);        }    }}